// STEP 1 (Ingestion) + request builder for STEP 2 (Classification)
// Mode: Run Once for Each Item. Normalises whatever arrived at the webhook
// into one internal shape, then builds the Groq chat-completions request.

const MODEL = 'llama-3.3-70b-versatile';

const SYSTEM_PROMPT = `You are the intake classifier for ArcVault, a B2B software company. You read one inbound customer message and classify it so it can be routed to the right team.

## Categories (choose exactly one)
- "Bug Report": something in the product is broken or behaves incorrectly for this customer (errors, failed actions, wrong results). Usually one user or one account.
- "Feature Request": the customer asks for a capability that does not exist today ("we'd love", "it would be great if", "please add").
- "Billing Issue": invoices, charges, payments, refunds, pricing or contract-rate questions.
- "Technical Question": how-to, configuration, integration or capability questions where nothing is broken ("is there a way to", "how do I", "do you support").
- "Incident/Outage": the service or a major part of it is unavailable or degraded for many users or the whole organisation ("down", "not loading for everyone", "multiple users affected").

## Tie-breaking rules
- Broken for one user/account -> "Bug Report". Broken for many users/an entire org, or the customer says it is on ArcVault's side -> "Incident/Outage".
- Asking whether something is possible -> "Technical Question", even if the answer might turn out to be "no, but we could build it".
- If money or invoices are the main subject -> "Billing Issue", even if a bug caused it.

## Priority (choose exactly one)
- "High": customers are blocked from using the product, many users affected, data/security risk, or financial impact on the customer.
- "Medium": a real problem with a workaround or limited scope, or a billing discrepancy that needs correcting.
- "Low": requests, questions and ideas with no current impact.

## Confidence
A number from 0.0 to 1.0 describing how sure you are of the CATEGORY:
- 0.90-1.00: the message clearly matches one category and no other category is plausible.
- 0.70-0.89: one category is most likely but another is plausible.
- below 0.70: the message is ambiguous, off-topic, too short, or fits two categories about equally.
Do not default to high confidence. Lower it whenever a tie-breaking rule was needed.

## Output
Return ONLY a JSON object, no prose, with exactly these keys in this order:
{
  "rationale": "one or two sentences explaining the decision, citing words from the message",
  "category": "Bug Report | Feature Request | Billing Issue | Technical Question | Incident/Outage",
  "secondary_category": "the next most plausible category, or null",
  "priority": "Low | Medium | High",
  "confidence": 0.0
}

## Examples
Message: "Exports to CSV have been timing out since this morning for my account only."
{"rationale":"A product function (CSV export) is failing for a single account, so it is a defect rather than an outage.","category":"Bug Report","secondary_category":"Incident/Outage","priority":"Medium","confidence":0.86}

Message: "Can we get dark mode please? Our team works late."
{"rationale":"Asks for a new capability ('can we get dark mode') with no current breakage.","category":"Feature Request","secondary_category":null,"priority":"Low","confidence":0.96}`;

// Webhook node puts the POST body under $json.body; accept a few field names
// so email / form / portal adapters can all post here.
const body = $json.body ?? $json;
const message = String(body.message ?? body.text ?? body.content ?? '').trim();

const request = {
  request_id: String(body.id ?? `REQ-${Date.now()}`),
  source: String(body.source ?? 'Unknown'),
  received_at: new Date().toISOString(),
  raw_message: message,
};

return {
  json: {
    ...request,
    llm_request: {
      model: MODEL,
      temperature: 0,
      response_format: { type: 'json_object' },
      messages: [
        { role: 'system', content: SYSTEM_PROMPT },
        {
          role: 'user',
          content: `Source channel: ${request.source}\nMessage:\n"""\n${message || '(empty message)'}\n"""`,
        },
      ],
    },
  },
};

// Validates the classifier output (never trust raw LLM JSON) and builds the
// request for STEP 3 (Enrichment).
// Mode: Run Once for Each Item.

const MODEL = 'llama-3.3-70b-versatile';
const CATEGORIES = ['Bug Report', 'Feature Request', 'Billing Issue', 'Technical Question', 'Incident/Outage'];
const PRIORITIES = ['Low', 'Medium', 'High'];

const ENRICH_PROMPT = `You are the enrichment step of ArcVault's support intake pipeline. You receive one customer message plus the category it has already been given. Extract structured facts and write a short hand-off summary for the team that will receive it.

## Rules
- Extract identifiers EXACTLY as written in the message. Never invent, normalise or guess an identifier. If a list has nothing, return an empty list.
- Amounts: return plain numbers (1240, not "$1,240"). "charged" = what the customer was billed; "expected" = what they believe they should have been billed. Use null when not stated. Do NOT calculate differences; downstream code does that.
- urgency_signal.level reflects the language and impact in the message itself (blocked work, many users, deadlines, money), not the category.
- urgency_signal.evidence must be a short phrase copied from the message, or null.
- core_issue: one sentence, plain language, no customer names.
- summary: 2-3 sentences written for the receiving internal team. Say what happened, what the customer needs, and the most useful next step. Do not promise anything to the customer and do not repeat the category label.

## Output
Return ONLY a JSON object with exactly these keys:
{
  "core_issue": "string",
  "identifiers": {
    "account_ids": [],
    "invoice_numbers": [],
    "error_codes": [],
    "urls": [],
    "products_or_features": [],
    "other": []
  },
  "amounts": { "charged": null, "expected": null, "currency": null },
  "urgency_signal": { "level": "low | medium | high", "evidence": "string or null" },
  "affected_scope": "single user | multiple users | whole organisation | unknown",
  "summary": "string"
}`;

const req = $('Prepare Classification').item.json;
const errors = [];

let parsed = {};
try {
  parsed = JSON.parse($json.choices?.[0]?.message?.content ?? '');
} catch (e) {
  errors.push('classifier returned invalid JSON');
}

const category = CATEGORIES.includes(parsed.category) ? parsed.category : null;
if (!category) errors.push(`unknown category: ${JSON.stringify(parsed.category ?? null)}`);

const priority = PRIORITIES.includes(parsed.priority) ? parsed.priority : 'Medium';
if (!PRIORITIES.includes(parsed.priority)) errors.push('priority missing/invalid, defaulted to Medium');

let confidence = Number(parsed.confidence);
if (!Number.isFinite(confidence)) {
  confidence = 0;
  errors.push('confidence missing, set to 0');
}
if (confidence > 1 && confidence <= 100) confidence = confidence / 100; // model answered in %
confidence = Math.round(Math.min(Math.max(confidence, 0), 1) * 100) / 100;

const secondary = CATEGORIES.includes(parsed.secondary_category) ? parsed.secondary_category : null;

const classification = {
  category,
  secondary_category: secondary,
  priority,
  confidence,
  rationale: String(parsed.rationale ?? ''),
  validation_errors: errors,
};

return {
  json: {
    request_id: req.request_id,
    source: req.source,
    received_at: req.received_at,
    raw_message: req.raw_message,
    classification,
    llm_request: {
      model: MODEL,
      temperature: 0,
      response_format: { type: 'json_object' },
      messages: [
        { role: 'system', content: ENRICH_PROMPT },
        {
          role: 'user',
          content: `Category: ${category ?? 'Unclassified'}\nSource channel: ${req.source}\nMessage:\n"""\n${req.raw_message}\n"""`,
        },
      ],
    },
  },
};

// STEP 4 (Routing) + STEP 5 (Structured output) + STEP 6 (Escalation flag)
// Deterministic rules only: no LLM decides where a ticket goes.
// Mode: Run Once for Each Item.

const CONFIG = {
  MODEL: 'llama-3.3-70b-versatile',
  PIPELINE_VERSION: '1.0.0',
  CONFIDENCE_THRESHOLD: 0.7,
  BILLING_ESCALATION_USD: 500,
  ESCALATION_QUEUE: 'Human Review',
  ROUTES: {
    'Bug Report': 'Engineering',
    'Incident/Outage': 'Engineering On-Call',
    'Feature Request': 'Product',
    'Billing Issue': 'Billing',
    'Technical Question': 'Technical Support',
  },
  // Phrases that always need a human, regardless of what the model said.
  ESCALATION_PATTERNS: [
    { label: 'outage', re: /\boutage\b/i },
    { label: 'down for all users', re: /\bdown for (all|every(one|body))\b/i },
    { label: 'multiple users affected', re: /\b(multiple|many|all) users\b/i },
    { label: 'data loss', re: /\bdata (loss|lost|deleted)\b/i },
    { label: 'security breach', re: /\b(breach|compromised|unauthori[sz]ed access)\b/i },
  ],
};

const prev = $('Validate Classification').item.json;
const c = prev.classification;
const notes = [...c.validation_errors];

// ---- parse + sanitise enrichment output ---------------------------------
let e = {};
try {
  e = JSON.parse($json.choices?.[0]?.message?.content ?? '');
} catch (err) {
  notes.push('enrichment returned invalid JSON');
}
const list = (v) => (Array.isArray(v) ? v.map(String).filter(Boolean) : []);
const num = (v) => {
  if (v === null || v === undefined || v === '') return null;
  const n = Number(String(v).replace(/[^0-9.\-]/g, ''));
  return Number.isFinite(n) ? n : null;
};
const ids = e.identifiers ?? {};
const level = ['low', 'medium', 'high'].includes(e.urgency_signal?.level) ? e.urgency_signal.level : 'medium';

const enrichment = {
  core_issue: String(e.core_issue ?? ''),
  identifiers: {
    account_ids: list(ids.account_ids),
    invoice_numbers: list(ids.invoice_numbers),
    error_codes: list(ids.error_codes),
    urls: list(ids.urls),
    products_or_features: list(ids.products_or_features),
    other: list(ids.other),
  },
  amounts: {
    charged: num(e.amounts?.charged),
    expected: num(e.amounts?.expected),
    currency: e.amounts?.currency ?? null,
  },
  urgency_signal: { level, evidence: e.urgency_signal?.evidence ?? null },
  affected_scope: String(e.affected_scope ?? 'unknown'),
};

// ---- escalation rules (STEP 6) --------------------------------------------
const reasons = [];
if (!c.category) reasons.push('classification failed validation');
if (c.confidence < CONFIG.CONFIDENCE_THRESHOLD) {
  reasons.push(`confidence ${c.confidence} is below ${CONFIG.CONFIDENCE_THRESHOLD}`);
}
if (c.category === 'Incident/Outage') reasons.push('category is Incident/Outage');
for (const p of CONFIG.ESCALATION_PATTERNS) {
  if (p.re.test(prev.raw_message)) reasons.push(`message matches escalation phrase "${p.label}"`);
}
// Billing: the model extracts the numbers, code does the arithmetic.
let billingDiscrepancy = null;
const { charged, expected } = enrichment.amounts;
if (charged !== null && expected !== null) {
  billingDiscrepancy = Math.round((charged - expected) * 100) / 100;
  if (Math.abs(billingDiscrepancy) > CONFIG.BILLING_ESCALATION_USD) {
    reasons.push(`billing discrepancy $${Math.abs(billingDiscrepancy)} exceeds $${CONFIG.BILLING_ESCALATION_USD}`);
  }
}

// ---- routing (STEP 4) -----------------------------------------------------
const standardQueue = CONFIG.ROUTES[c.category] ?? null; // null => fallback
const escalate = reasons.length > 0 || !standardQueue;
const queue = escalate ? CONFIG.ESCALATION_QUEUE : standardQueue;

// Outages are always High, whatever the model said.
let priority = c.priority;
if (c.category === 'Incident/Outage' && priority !== 'High') {
  priority = 'High';
  notes.push('priority raised to High for Incident/Outage');
}

// ---- final record (STEP 5) ------------------------------------------------
return {
  json: {
    request_id: prev.request_id,
    source: prev.source,
    received_at: prev.received_at,
    raw_message: prev.raw_message,
    category: c.category,
    priority,
    confidence: c.confidence,
    classification_rationale: c.rationale,
    secondary_category: c.secondary_category,
    core_issue: enrichment.core_issue,
    identifiers: enrichment.identifiers,
    amounts: { ...enrichment.amounts, discrepancy: billingDiscrepancy },
    urgency_signal: enrichment.urgency_signal,
    affected_scope: enrichment.affected_scope,
    routing: {
      destination_queue: queue,
      standard_queue: standardQueue,
      reason: escalate
        ? `Escalated for human review; would otherwise go to ${standardQueue ?? 'no queue (unclassified)'}.`
        : `${c.category} -> ${standardQueue}`,
    },
    escalation: { flagged: escalate, reasons },
    summary: String(e.summary ?? ''),
    processing_notes: notes,
    meta: {
      model: CONFIG.MODEL,
      pipeline_version: CONFIG.PIPELINE_VERSION,
      processed_at: new Date().toISOString(),
    },
  },
};
